/* Les deux types sans code fixe : la regle que la RFC donne a la place. */
const REGLES = {
  http_request_error: 'le code 4xx en cause',
  proxy_internal_response: 'le code le plus approprie a la reponse'
};

export const ERREURS_PROXY = E.map(([nom, sens, statut, intermediaire, reference, extras]) => ({
  nom, sens, statut, statutRegle: REGLES[nom] || null, intermediaire, reference,
  extras: extras.map(([cle, type, s]) => ({ cle, type, sens: s }))
}));

/** Le type d erreur de ce nom, ou null. */
export const erreurProxy = nom => ERREURS_PROXY.find(e => e.nom === nom) || null;

/* Les parametres des membres de Proxy-Status (registre « HTTP Proxy-Status
   Parameters »). */
export const PARAMETRES_PROXY = [
  { cle: 'error', sens: 'le type d erreur rencontre par l intermediaire en obtenant cette reponse', reference: 'RFC 9209' },
  { cle: 'next-hop', sens: 'l intermediaire ou le serveur d origine choisi comme saut suivant (et employe, s il a ete joint) : nom d hote, adresse IP ou alias', reference: 'RFC 9209' },
  { cle: 'next-protocol', sens: 'l identifiant ALPN du protocole employe vers le saut suivant', reference: 'RFC 9209' },
  { cle: 'received-status', sens: 'le code de statut que l intermediaire a recu du saut suivant', reference: 'RFC 9209' },
  { cle: 'details', sens: 'des informations supplementaires, propres a l implementation ou au deploiement', reference: 'RFC 9209' },
  { cle: 'next-hop-aliases', sens: 'les alias DNS et noms canoniques rencontres en resolvant le nom du saut suivant', reference: 'RFC 9532' }
];

/* Les parametres supplementaires de tous les types : un parametre connu
   pose sur un type qui ne le definit pas est ignore (RFC 9209 §2.1.1). */
export const EXTRAS_PROXY = new Set(ERREURS_PROXY.flatMap(e => e.extras.map(x => x.cle)));
